import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';

export function middleware(request: NextRequest) {
  // Log the request pathname to the console
  console.log(`[Middleware] Request Pathname: ${request.nextUrl.pathname}`);

  // Create the response object
  const response = NextResponse.next();

  // Add the custom X-Request-Id header with a unique UUID
  response.headers.set('X-Request-Id', crypto.randomUUID());

  return response;
}

// Optional: Configure the middleware to match specific paths.
// This standard matcher excludes static assets and Next.js internals.
export const config = {
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)',
  ],
};
